 const ВІДБИТОК_ПОКАЗУ = "__ВІДБИТОК__";
+
+/* ── ЧИ Є НОВІША ЗБІРКА ──────────────────────────────────────────────────
+   GitHub Pages віддає index.html з max-age=600, а відновлена вкладка й вбудовані
+   браузери месенджерів тримають копію ще довше. CI кладе поруч `build.txt` зі
+   штампом збірки; при відкритті й коли вкладка знову видима читаємо його повз кеш.
+   Лише смужка з кнопкою: сторінку сама не перезавантажуємо, щоб не обірвати розмову. */
+const ФАЙЛ_ЗБІРКИ = 'build.txt';
+function шляхОновлення(нова, адреса){
+  const у = new URL(адреса);
+  у.searchParams.set('v', нова);
+  return у.pathname + у.search + у.hash;
+}
+async function перевіритиНовішуЗбірку(){
+  if (!/^https?:$/.test(location.protocol) || ЗБІРКА_ПОКАЗУ.indexOf('показ') < 0) return;
+  try{
+    const відп = await fetch(new URL(ФАЙЛ_ЗБІРКИ, location.href).pathname + '?t=' + Date.now(), {cache:'no-store'});
+    if (!відп.ok){ console.warn('штамп збірки: ' + ФАЙЛ_ЗБІРКИ + ' → ' + відп.status); return; }
+    const нова = (await відп.text()).trim();
+    if (!нова || нова === ЗБІРКА_ПОКАЗУ) return;
+    $('нова-версія').hidden = false;
+    $('нова-версія-кн').onclick = () => location.replace(шляхОновлення(нова, location.href));
+  }catch(e){ console.warn('штамп збірки не прочитано:', e); }
+}
+перевіритиНовішуЗбірку();
+document.addEventListener('visibilitychange', () => {
+  if (document.visibilityState === 'visible') перевіритиНовішуЗбірку();
+});
